/* Local-first personal candidate management; no messages or profile data leave this app. */
const storageKey='yujian-bazi-local-v1';
const samplePeople=people.map(p=>({...p})),sampleBirths=JSON.parse(JSON.stringify(demoBirths));
let storageWarning=false,removedCandidate=null,recoveryBlocked=false,recoveryRaw=null;
function avatarData(name){return 'data:image/svg+xml;base64,'+btoa(unescape(encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="180" height="220"><rect width="180" height="220" rx="18" fill="#efe7f3"/><text x="90" y="124" text-anchor="middle" font-family="sans-serif" font-size="64" fill="#95739e">${esc(name.slice(0,1))}</text></svg>`)))}
function stateSnapshot(){return {version:1,birth:myBirth,profile,people,births:demoBirths,likes:[...likes],skipped:[...skipped],filter,interests:[...myInterests]}}
function saveLocal(){if(recoveryBlocked){storageWarning=true;return}try{localStorage.setItem(storageKey,JSON.stringify(stateSnapshot()));storageWarning=false}catch{storageWarning=true}}
function validatedState(data){
  if(!data||data.version!==1||!Array.isArray(data.people)||data.people.length>500||!data.births||!data.profile)throw Error('备份格式不正确');
  birthChart(data.birth);if(adultAge(data.birth.date)<18||adultAge(data.birth.date)>100)throw Error('备份中的个人年龄不符合要求');
  const ids=new Set();const cleanPeople=data.people.map(p=>{if(!Number.isSafeInteger(p.id)||p.id<1||ids.has(p.id))throw Error('候选编号有误');ids.add(p.id);const birth=data.births[p.id];birthChart(birth);if(adultAge(birth.date)<18||adultAge(birth.date)>100)throw Error('候选年龄不符合要求');const clean={id:p.id};for(const key of ['name','job','area','contact'])clean[key]=typeof p[key]==='string'?p[key].trim().slice(0,key==='contact'?160:40):'';if(!clean.name)throw Error('候选姓名缺失');clean.age=adultAge(birth.date);clean.km=Number.isFinite(p.km)&&p.km>=0?Math.min(p.km,10000):null;clean.tags=Array.isArray(p.tags)?p.tags.filter(t=>typeof t==='string').slice(0,12).map(t=>t.slice(0,20)):[];clean.image=typeof p.image==='string'&&(/^data:image\/(png|jpeg|webp|svg\+xml);base64,/.test(p.image)||p.image.startsWith('https://images.unsplash.com/'))?p.image:avatarData(clean.name);clean.bio=typeof p.bio==='string'?p.bio.slice(0,300):'从共同兴趣开始认识。';clean.headline='先认识，再决定。';clean.prompt='可以聊聊…';clean.answer='各自最喜欢的生活方式，以及对关系的期待。';clean.demo=!!p.demo;return clean});
  const cleanProfile={...profile};for(const key of ['name','city','job','bio'])if(typeof data.profile[key]==='string')cleanProfile[key]=data.profile[key].slice(0,key==='bio'?200:30);cleanProfile.age=adultAge(data.birth.date);
  return {birth:{date:data.birth.date,time:data.birth.time||'',unknown:!!data.birth.unknown,demo:!!data.birth.demo},profile:cleanProfile,people:cleanPeople,births:Object.fromEntries(cleanPeople.map(p=>[p.id,{date:data.births[p.id].date,time:data.births[p.id].time||'',unknown:!!data.births[p.id].unknown}])),likes:new Set((Array.isArray(data.likes)?data.likes:[]).filter(id=>ids.has(id))),skipped:new Set((Array.isArray(data.skipped)?data.skipped:[]).filter(id=>ids.has(id)))}
}
function restoreLocal(data){const s=validatedState(data);recoveryBlocked=false;recoveryRaw=null;removedCandidate=null;myBirth=s.birth;profile=s.profile;people.splice(0,people.length,...s.people);for(const k of Object.keys(demoBirths))delete demoBirths[k];Object.assign(demoBirths,s.births);likes=s.likes;skipped=s.skipped;history=[];index=0;if(Array.isArray(data.interests))myInterests.splice(0,myInterests.length,...data.interests.filter(v=>typeof v==='string').slice(0,12).map(v=>v.slice(0,20)));if(data.filter&&Number.isFinite(data.filter.min)&&Number.isFinite(data.filter.max)&&data.filter.min>=18&&data.filter.max<=100&&data.filter.min<=data.filter.max)filter={min:data.filter.min,max:data.filter.max,distance:Number.isFinite(data.filter.distance)?Math.max(1,Math.min(10000,data.filter.distance)):10000};chartCache.clear()}
const baseRender=render,baseBazi=renderBazi,baseProfile=renderProfile;
renderProfile=function(){if(myBirth.demo)return heading('从真实的你开始','先保存自己的生辰，再建立候选列表。')+`<div class="empty">${icon('user')}<h2>填写你的第一份资料</h2><p>资料只保存在当前浏览器中。</p><button class="primary-btn" data-page="bazi">填写我的生辰</button></div>`;return baseProfile().replace('这是演示资料。当前修改会在刷新后重置。','资料已保存在当前浏览器。建议定期导出备份。')};
renderBazi=function(){let html=baseBazi();html=html.replace('生辰仅在此页面计算，刷新后重置。','资料保存在当前浏览器，不上传服务器。').replace('候选资料均为虚构。','候选人来自你自行录入的资料。').replace('候选资料均为虚构','候选人来自你自行录入的资料');if(myBirth.demo)html=html.replace('按合缘参考分排序，同分时优先共同兴趣。','当前展示示例生辰，请先填写并保存自己的生辰。');html=html.replace('<form id="birth-form">',`<form id="birth-form"><label class="field birth-name">我的昵称<input name="nickname" aria-label="我的昵称" value="${esc(myBirth.demo?'':profile.name)}" placeholder="填写昵称" maxlength="20" required></label>`);html=html.replace('暂时没有新的候选','还没有可匹配的候选').replace('可以调整偏好，或者去看看已经喜欢的人。','先添加候选人的生辰资料，再查看八字合缘。').replace('<button class="outline-btn" data-action="filter">调整偏好</button><button class="primary-btn" data-page="likes">查看喜欢</button>','<button class="primary-btn" data-action="add-person">添加候选人</button><button class="outline-btn" data-action="load-samples">用示例试用</button>');return html};
function renderPeople(){return heading('候选人资料库','录入生辰，保存联系信息，让每一次比较有据可查。',`<button class="primary-btn" data-action="add-person">添加候选人</button>`)+`<div class="local-toolbar"><span>共 ${people.length} 人 · 仅保存在本机浏览器</span><div><button class="outline-btn" data-action="export-data">导出备份</button><button class="outline-btn" data-action="import-data">导入备份</button><input id="import-file" type="file" accept=".json,application/json" hidden></div></div>${people.length?`<div class="people-list">${people.map(p=>`<article class="saved-person"><img src="${p.image}" alt=""><div><h2>${esc(p.name)} <small>${adultAge(demoBirths[p.id].date)} 岁${p.demo?' · 示例':''}</small></h2><p>公历 ${demoBirths[p.id].date} · ${demoBirths[p.id].unknown?'时辰不详':demoBirths[p.id].time}</p><p>${esc(p.job||'未填写职业')} · ${esc(p.area||'未填写城市')}</p></div><div class="saved-actions"><button class="primary-btn" data-compare="${p.id}">查看合缘</button><button class="outline-btn" data-edit-person="${p.id}">编辑</button><button class="text-danger" data-delete-person="${p.id}">移除</button></div></article>`).join('')}</div>`:`<div class="empty">${icon('user')}<h2>添加你的第一位候选人</h2><p>填写对方提供的生辰，软件会计算四柱和合缘参考。</p><button class="primary-btn" data-action="add-person">添加候选人</button><button class="outline-btn" data-action="load-samples">用示例试用</button></div>`}${removedCandidate?'<button class="outline-btn" data-action="restore-person">撤销上次移除</button>':''}<p class="muted">请仅录入已获得对方同意的信息。导出的备份包含生辰和联系方式，请保存在自己的设备中。</p>`}
render=function(){if(page==='people'){document.querySelectorAll('[data-page]').forEach(el=>el.classList.toggle('active',el.dataset.page===page));document.getElementById('breadcrumb').textContent='资料 / 候选人';app.innerHTML=renderPeople();document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon))}else baseRender();document.querySelectorAll('[data-chat]').forEach(button=>{button.removeAttribute('data-chat')});saveLocal();if(storageWarning&&!document.getElementById('storage-warning')){const warning=document.createElement('p');warning.id='storage-warning';warning.className='storage-warning';warning.textContent=recoveryBlocked?'原有资料暂时无法读取，已保留原始数据并暂停自动保存。可在候选人页面导入有效备份。':'当前浏览器无法保存资料。请在关闭前导出备份。';if(recoveryRaw){const button=document.createElement('button');button.className='outline-btn';button.textContent='导出原始资料';button.onclick=()=>{const url=URL.createObjectURL(new Blob([recoveryRaw],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='遇见-原始资料恢复.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};warning.appendChild(button)}app.prepend(warning)}};
function candidateForm(id){const p=people.find(p=>p.id===id),birth=p?demoBirths[id]:{date:'',time:'',unknown:false};modal(`<div class="dialog-head"><h2>${p?'编辑候选资料':'添加候选人'}</h2>${closeButton()}</div><form id="candidate-form" data-id="${id||''}"><div class="age-fields"><label class="field">昵称<input name="name" value="${esc(p?.name||'')}" maxlength="20" required></label><label class="field">出生日期 · 公历<input type="date" name="date" aria-label="候选出生日期" min="1900-01-01" value="${birth.date}" required></label></div><label class="field">出生时间 · 东八区标准时间<input type="time" name="time" aria-label="候选出生时间" value="${birth.time}" ${birth.unknown?'disabled':'required'}></label><label class="unknown-hour"><input name="unknown" type="checkbox" ${birth.unknown?'checked':''}>不清楚出生时辰</label><div class="age-fields"><label class="field">职业<input name="job" maxlength="30" value="${esc(p?.job||'')}"></label><label class="field">城市<input name="area" maxlength="30" value="${esc(p?.area||'')}"></label></div><label class="field">兴趣 · 用逗号分隔<input name="tags" maxlength="150" value="${esc(p?.tags.join('，')||'')}"></label><label class="field">联系方式 · 可选<input name="contact" maxlength="160" value="${esc(p?.contact||'')}" placeholder="例如微信号或手机号，仅保存于本机"></label><p class="birth-note">仅限18岁及以上成年人。请先换算夏令时或海外时间；软件不自动校正真太阳时。</p><button type="submit" class="primary-btn full">保存并参与匹配</button></form>`);dialog.classList.add('bazi-dialog')}
function showContact(id){const p=people.find(p=>p.id===id);modal(`<div class="dialog-head"><h2>${esc(p.name)}的联系方式</h2>${closeButton()}</div><p class="contact-value">${esc(p.contact||'尚未填写联系方式')}</p><p class="muted">联系信息由你录入，软件不会代发消息。</p><button class="outline-btn full" data-edit-person="${id}">编辑资料与联系方式</button>`)}
function exportData(){const blob=new Blob([JSON.stringify(stateSnapshot(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='遇见-资料备份-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('备份已导出')}
document.addEventListener('submit',e=>{if(e.target.id==='birth-form'){const nickname=new FormData(e.target).get('nickname')?.trim();if(nickname){profile.name=nickname;saveLocal();render()}return}if(e.target.id!=='candidate-form')return;e.preventDefault();const data=new FormData(e.target);try{const birth={date:data.get('date'),time:data.get('time')||'',unknown:data.has('unknown')};birthChart(birth);const age=adultAge(birth.date);if(age<18||age>100)throw Error('候选人必须为18岁及以上成年人，请检查出生日期');const name=data.get('name').trim();if(!name)throw Error('请填写昵称');const id=Number(e.target.dataset.id)||Math.max(Date.now(),removedCandidate?.p.id+1||0,...people.map(p=>p.id+1)),old=people.find(p=>p.id===id);const record={id,name,age,job:data.get('job').trim()||'未填写职业',area:data.get('area').trim()||'未填写城市',tags:data.get('tags').split(/[,，、]/).map(t=>t.trim()).filter(Boolean).slice(0,12),contact:data.get('contact').trim(),km:old?.km??null,image:old?.image||avatarData(name),headline:'先认识，再决定。',bio:'从共同兴趣与生活方式，了解真实的彼此。',prompt:'可以聊聊…',answer:'各自期待怎样的关系，以及平日里喜欢做的事。',demo:false};if(old)people.splice(people.indexOf(old),1,record);else people.push(record);demoBirths[id]=birth;chartCache.clear();dialog.close();page='people';render();toast('资料已保存，合缘结果已更新')}catch(err){toast(err.message)}});
document.addEventListener('change',e=>{if(e.target.matches('#candidate-form [name=unknown]')){const input=document.querySelector('#candidate-form [name=time]');input.disabled=e.target.checked;input.required=!e.target.checked}if(e.target.id==='import-file'&&e.target.files[0]){const file=e.target.files[0];if(file.size>6*1024*1024){toast('备份文件过大，最多支持6MB');return}file.text().then(text=>{try{const raw=JSON.parse(text),check=validatedState(raw);modal(`<div class="dialog-head"><h2>导入资料备份</h2>${closeButton()}</div><p class="muted">此备份包含 ${check.people.length} 位候选人。导入会替换当前资料，建议先导出当前备份。</p><button class="outline-btn full" data-action="export-data">先导出当前资料</button><button class="primary-btn full compare-chat" id="confirm-import">确认替换并导入</button>`);document.getElementById('confirm-import').addEventListener('click',()=>{restoreLocal(raw);dialog.close();page='people';render();toast('备份已导入')})}catch(err){toast('无法导入：'+err.message)}}).catch(()=>toast('文件读取失败'))}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const action=b.dataset.action;if(action==='add-person'){candidateForm();return}if(b.dataset.editPerson){if(dialog.open)dialog.close();candidateForm(Number(b.dataset.editPerson));return}if(b.dataset.contact){showContact(Number(b.dataset.contact));return}if(b.dataset.deletePerson){const id=Number(b.dataset.deletePerson),p=people.find(p=>p.id===id);removedCandidate={p,birth:demoBirths[id],liked:likes.has(id)};people.splice(people.indexOf(p),1);delete demoBirths[id];likes.delete(id);skipped.delete(id);render();toast('已移除，可撤销');return}if(action==='restore-person'&&removedCandidate){people.push(removedCandidate.p);demoBirths[removedCandidate.p.id]=removedCandidate.birth;if(removedCandidate.liked)likes.add(removedCandidate.p.id);removedCandidate=null;render();return}if(action==='load-samples'){const next=Math.max(Date.now(),removedCandidate?.p.id||0,...people.map(p=>p.id));samplePeople.forEach((p,i)=>{const id=next+i+1;people.push({...p,id,demo:true,contact:''});demoBirths[id]=sampleBirths[p.id]});render();toast('已载入3位示例候选人');return}if(action==='export-data')exportData();if(action==='import-data')document.getElementById('import-file').click()});
try{const saved=localStorage.getItem(storageKey);if(saved){recoveryRaw=saved;restoreLocal(JSON.parse(saved));}else{people.splice(0);for(const k of Object.keys(demoBirths))delete demoBirths[k];profile.name='我'}}catch{recoveryBlocked=true;storageWarning=true;people.splice(0);for(const k of Object.keys(demoBirths))delete demoBirths[k]}
page='bazi';render();
